create temp table r48trk_done on commit drop as select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-tracker-events', 'Tracker events and pound flags', 'What the Tracker records, who is told, how a speeding record is charged with its evidence, and what to do when a car is at a pound.', array['va/fleet', 'admin/fleet-and-listings']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-tracker-events'), 1, 'One event, one alert', '[{"caption":"Tracker events","say":"When Tracker events are on, the Tracker makes one alert per car, kind and thirty minutes. Never a flood. Each alert has an evidence record: the map point, the speed, the time and where it came from.","visual":{"kind":"title","heading":"One event, one alert","text":"With its evidence record"}},{"caption":"What it records","say":"Speeding over 180, 220 or 300 kilometres an hour. Harsh driving. The car outside Ontario. Driving after the return time. The Tracker unplugged or tampered with. And a car parked at a pound.","visual":{"kind":"list","heading":"Events","items":["Speeding over 180, 220, 300 km/h","Harsh driving","Outside Ontario","Driving after the return time","Tracker unplugged or tampered with","Parked at a pound"]}},{"caption":"Who is told","say":"The renter is told by themselves: what happened, the charge and the clause of the agreement, in calm words. The car''s owner is told the event and the place, never the renter or the booking. You do not message them about the event itself.","visual":{"kind":"list","heading":"Told by themselves","items":["Renter: what happened, the charge, the clause","Owner: the event and the place only","Staff: the alert and the evidence"]}},{"caption":"The charge","say":"Only a speeding record over a limit carries a set charge: 500, 1,000 or 2,500 dollars plus HST. One event is one charge, at the highest limit reached. An Admin or Finance presses Charge on the record. The evidence is attached by itself and goes into the dispute pack.","visual":{"kind":"rule","heading":"Charge with evidence","text":"One event, one charge, at the highest limit reached. An Admin or Finance presses Charge.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-tracker-events'), 2, 'A car at a pound', '[{"caption":"The flag","say":"A car whose Tracker parks at a known pound lot is flagged. Fleet gets an urgent To do and alert. The flag shows the lot, its phone and its hours.","visual":{"kind":"title","heading":"At a pound","text":"An urgent To do for Fleet"}},{"caption":"Call first","say":"Call the lot to confirm the car is there and what releases it. Then call the renter. Keep every receipt: the tow, the impound and the storage.","visual":{"kind":"list","heading":"Do now","items":["Call the lot","Call the renter","Keep every receipt"]}},{"caption":"Record the path","say":"Then press Record the path. Non-return, for a car not back after the final late notice. Theft recovery, for a car stolen or recovered by the police. Recovered with nothing to charge. Or not a pound. Write what happened in one sentence.","visual":{"kind":"list","heading":"The path","items":["Non-return charge and the costs","Theft recovery charge and the costs","Recovered, nothing to charge","Not a pound"]}},{"caption":"Evidence still counts","say":"A charge still waits for its other evidence, like every fee: the final late notice for non-return, the police report for theft, and the receipts for the costs.","visual":{"kind":"rule","heading":"Evidence for every fee","text":"The final notice, the police report and the receipts are still needed.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 1, 'The Tracker records 190 km/h three times in one minute. How many alerts are made?', '["Three", "One", "None until an Admin looks", "One per reading and one per minute"]'::jsonb, 1, 'One event per car, kind and 30 minutes: never a flood.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 2, 'Who presses Charge on a speeding record over 180 km/h?', '["Anyone on staff", "Field staff at the return", "An Admin or Finance", "The car''s owner"]'::jsonb, 2, 'An Admin or Finance charges it; the Tracker evidence record is attached by itself.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 3, 'What does the car''s owner see about a speeding event?', '["The renter''s name and phone", "The booking and its price", "The event and the place only", "Nothing at all"]'::jsonb, 2, 'The owner is told the event and the place, never the renter or the booking.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 4, 'A car is flagged at a pound. What do you do first?', '["Charge the non-return fee at once", "Call the lot, then the renter, and keep the receipts", "Mark it Not a pound", "Wait for the renter to call"]'::jsonb, 1, 'Confirm with the lot, call the renter, keep the receipts, then record the path.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 5, 'The Tracker records 226 km/h in one event. What is charged?', '["$500 and $1,000", "$1,000: one charge, at the highest limit reached", "$2,500", "Nothing until the return"]'::jsonb, 1, 'One event is one charge, at the highest limit reached (rental agreement 10.5).') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-tracker-events'), 6, 'The Tracker records hard braking several times. What does the renter get?', '["A $500 charge", "A friendly heads-up with no charge", "Nothing", "The rental is ended"]'::jsonb, 1, 'Harsh driving is a heads-up only: no set charge under the agreement.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'r48-tracker-events'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'finance', (select id from academy_sections where slug = 'r48-tracker-events'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'finance' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'cs', (select id from academy_sections where slug = 'r48-tracker-events'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'cs' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'r48-tracker-events'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days') from r48trk_done d where e.user_id = d.user_id and e.gate;

-- GUIDES 3322 START (generated by supabase/seed/3322_gen_guides.mjs from docs/guides/content; do not edit by hand)
select app.guide_release_section('renter', 'during-your-trip', 'chapter', 'before-pickup', 'Plans change. You can ask for more days, ask to change dates, answer a change we suggest, or cancel, all from your booking.

## Extend your rental

1. On your booking, press **Extend**.
2. Pick how long: **1 hour**, **3 hours**, **1 day**, **3 days**, **1 week** or **1 month**. Each shows the new return and its price, HST included: each added day costs your booking''s price a day (what you paid for it, fees and HST included, divided by its days). An option the car cannot take is greyed out with the reason, and the page says until when the car is free.
3. Press **Pay** to pay with your card on file. When the car is free it is approved at once and the page shows your new return. No card on file, or the card is declined? The secure payment page opens: enter a card there. Otherwise the request goes to our team, and once approved you pay on the same page.
4. For another date, open **Another date and time**, choose it, press **See the price**, then **Request extension**.

![](/guides/img/renter-11-extend-desktop-957274cc.jpg "desktop; size: 960 552; address: carmacars.ca/account/bookings/CC-10003/extend; pins: 2 34.4 62.9, 3 15.1 77.2")

> Tip: A few hours cost the hourly late fee, never more than a day, so extending never costs more than being late, and it keeps your trip covered. Already past your return time and still have the car? You can still extend. It counts from your original return time, and the late charges stay owed until the extension is paid.

## Ask to change dates

1. On your booking, press **Ask to change dates**.
2. Set the new pickup and return, then press **See the difference** to see what you would pay or get back.
3. Press **Ask to change dates** to send it. Nothing changes until you agree to our answer.

![](/guides/img/renter-12-change-desktop-09f6b563.jpg "desktop; size: 960 552; address: carmacars.ca/account/bookings/CC-10003/change; pins: 2 15.1 91.8")

## A change we suggest

Sometimes we need to change your booking, for example another car of the same class. You decide.

1. You get an email, and your booking says "We suggest a change to your booking". Press **Review and answer**.
2. Read what changes (before and after), the reason, the money and the time left to answer.
3. To agree, press **Accept and sign the amendment**, sign, then press **Accept and sign**.
4. Anything more to pay is charged to your Card on File. If the card is declined, press **Pay and apply the change**.
5. To say no, press **Decline this change**. Your booking stays as it was.

> Tip: You have 48 hours to answer, and we send one reminder. CarmaCars signs the amendment at the moment you sign it, and the signed copy is saved under Documents. If the change costs less, the refund goes back to your card within 10 business days after the amendment is signed.

## Cancel a booking

1. On your booking, press **Cancel booking**.
2. Read What you get back. It shows the rule that applies and your refund.
3. Type the booking number to confirm (for example CC-10021), then press **Cancel booking**.

![](/guides/img/renter-13-cancel-desktop-d0bb2c67.jpg "desktop; size: 1440 692; address: carmacars.ca/account/bookings/CC-10003/cancel; pins: 2 36.1 67.2, 3 95.8 45.1")

| Standard booking: when you cancel | Refund of what you paid |
| --- | --- |
| Within 24 hours of booking, and 48 hours or more before pickup | 95% back |
| 48 hours or more before pickup | 75% back |
| 24 to 48 hours before pickup | 50% back |
| Less than 24 hours before pickup | No refund |

A Non-refundable booking gets no refund. The deposit is taken at pickup, so none is held when you cancel before it.

## Messages, tolls and tickets

- On a rental of 2 days or more we check in after the first day: "How is the car?" If anything is off, reply to the email or text, or call us.
- Write to us about a booking at the bottom of its page: type in Your message and press Send.
- Tolls and tickets are yours to pay, including Highway 407 ETR. If one reaches us, we pay it and charge the amount plus our fee to your Card on File, and email you a copy of the notice.
- Running late? Extend in your booking, even after the return time while you still have the car, or call us at 289-312-5991. The late fee is 17.5% of the daily rate for each started hour (at least $25) after a 30 minute grace.
- Before your return we remind you: the day before, about 3 hours before (with an Extend link) and at the return time. If the car is late we send a notice at 15 minutes and a final notice at 2 hours. No late notices between 10 pm and 7 am.
- Already brought the car back but still getting late notices? Tap **I''ve returned the car** in the notice, or press it on your booking. Add photos of the car where you left it (pick several at once from your camera roll), the odometer, the fuel level and the time you returned it: all optional. The late notices stop at once while we check. When we confirm, your trip is complete. If we cannot find the car, we tell you why and the notices start again.
- Something wrong with the car? While you have it, press **Report a problem** on your booking: it calls roadside help, or opens a message to us.
- Someone else will drive too? Press **Add a driver**: write their name in the message and we add them; they sign with their own link.

## Return the car yourself (release 28)

**Return the car yourself** on your booking: photos of the car where you left it, the odometer, the fuel and the time. With all of them your trip is completed at once and any late notices stop; we may still adjust the readings after we see the car.

## Report an accident

While you have the car, the **Accident card** on your booking has **Report an accident**. Anyone hurt? Call 911 first.

1. Say what happened, when (empty means now) and where: type it or press **Use my location**.
2. Add photos and videos from your camera roll: all the cars, the plates, the damage and the scene.
3. Add the other party''s name, phone, plate and their insurer, and the police report number if there is one.
4. Answer **Is anyone hurt?** and **Can the car be driven?**, then press **Send the report**.

Your answers stay on your phone as you type until you send them. Once sent, our team has it at once and calls you; the page shows the next steps, **Call us**, and lets you add more photos or videos.

## Extend at the same rate (release 35)

An extension costs the same a day as your booking, and per-trip fees such as the Protection Plan are charged for the added days at the same rate. Delivery is never charged again. The price shows before you ask.

## Secondary contact and rideshare documents

Open **More** on your booking page:

- **Secondary contact**: someone we may call if we cannot reach you, for this trip or on your profile. Optional.
- **Rideshare or delivery documents**: rideshare and delivery driving are welcome. Driving for Uber, Lyft, DoorDash, Uber Eats, Instacart or another platform? Pick the platforms and print the documents they ask for: your rental agreement, a coverage letter and a vehicle letter.

## Rideshare, a second contact and a mid-trip check (release 35)

- Driving for Uber, Lyft, DoorDash, Uber Eats, Instacart or another platform is allowed: your booking page makes the documents they ask for.
- Add a secondary contact we can call if we cannot reach you, on your profile or for one trip.
- Halfway through a longer trip we send one short message asking how it is going. Reply with any problem and our team picks it up.
- We send no automatic text at night; an answer asked for then arrives in the morning. Common questions are answered at once, and a person answers anything else.

## Deposit still owed (release 48)
If you picked up the car before the deposit hold was placed, your booking page says **Deposit still owed** with the amount. It is a hold on your credit card, not a charge, released after the rental. We try your saved card each morning; if that does not work we send you a secure link by text or email. Tap it to place the hold, or call us.', 'During your trip', 'Extend, change dates, answer a change we suggest, or cancel.',
